def transform(grid):
    """Use the first decorated rectangular frame as a stencil. Stamp it into
    blank frames of matching width/compatible height; erase incompatible frames."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row if v != 0}
    boxes = {}
    for color in colors:
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        r0 = min(r for r, c in cells); r1 = max(r for r, c in cells)
        c0 = min(c for r, c in cells); c1 = max(c for r, c in cells)
        if (all(grid[r][c] == color for c in range(c0, c1 + 1) for r in (r0, r1))
            and all(grid[r][c] == color for r in range(r0, r1 + 1) for c in (c0, c1))):
            boxes[color] = (r0, r1, c0, c1)
    patterned = []
    for color, (r0, r1, c0, c1) in boxes.items():
        pat = [[grid[r][c] == color for c in range(c0 + 1, c1)]
               for r in range(r0 + 1, r1)]
        if any(any(row) for row in pat):
            patterned.append((r0, c0, color, pat))
    if not patterned:
        return out
    _, _, src_color, pattern = min(patterned)
    # Trim empty rows/columns from the stencil. The demo with a blank final
    # source row shows that frame size may exceed the actual pattern extent.
    rows = [r for r, row in enumerate(pattern) if any(row)]
    cols = [c for c in range(len(pattern[0])) if any(pattern[r][c] for r in range(len(pattern)))]
    pattern = [[pattern[r][c] for c in cols] for r in rows]
    src_h, src_w = len(pattern), len(pattern[0]) if pattern else 0
    for color, (r0, r1, c0, c1) in boxes.items():
        if color == src_color:
            continue
        inner_h, inner_w = r1 - r0 - 1, c1 - c0 - 1
        # A frame is compatible when it can take the stencil at its full width;
        # the source may have one extra all-filled row, which is clipped.
        compatible = inner_w == src_w and inner_h == src_h
        occupied = any(grid[r][c] == color
                       for r in range(r0 + 1, r1) for c in range(c0 + 1, c1))
        if not compatible:
            for r in range(r0, r1 + 1):
                for c in range(c0, c1 + 1):
                    if grid[r][c] == color:
                        out[r][c] = 0
        else:
            # Matching frames receive the source pattern; first clear any old
            # interior marks, then stamp the stencil in this frame's color.
            for r in range(r0 + 1, r1):
                for c in range(c0 + 1, c1):
                    out[r][c] = 0
            for dr in range(inner_h):
                for dc in range(inner_w):
                    if pattern[dr][dc]:
                        out[r0 + 1 + dr][c0 + 1 + dc] = color
    return out

